async def act(page):
    import asyncio
    import csv as _csv
    import re
    from collections import Counter
    from pathlib import Path

    async def safe_count(locator):
        try:
            return await locator.count()
        except Exception:
            return 0

    # We continue from the current Orders page state (do not change language settings).
    # 1) Locate the main Orders table (the one with header cell 'Order #')
    orders_table = page.get_by_role("table").filter(
        has=page.get_by_role("cell", name=lambda n: bool(n) and 'Order #' in n)
    ).first

    # 2) Determine index of the 'Bill to Name' header cell so we can later target the correct filter textbox
    bill_col_idx = None
    try:
        header_row = orders_table.get_by_role("row").nth(0)
        header_cells = header_row.get_by_role("cell")
        hdr_count = await safe_count(header_cells)
        for i in range(hdr_count):
            try:
                txt = (await header_cells.nth(i).inner_text()) or ''
            except Exception:
                txt = ''
            if 'Bill to Name' in txt:
                bill_col_idx = i
                break
    except Exception:
        pass

    if bill_col_idx is None:
        print('ERROR: Could not locate Bill to Name column')
        return

    # 3) In the filter row (usually row index 1) find a combobox that offers 'Canceled' and select it
    try:
        filter_row = orders_table.get_by_role('row').nth(1)
        comboboxes = filter_row.get_by_role('combobox')
        cb_count = await safe_count(comboboxes)
        for ci in range(cb_count):
            cb = comboboxes.nth(ci)
            try:
                opts = await cb.get_by_role('option').all_inner_texts()
            except Exception:
                opts = []
            chosen = None
            for o in opts:
                if o and 'canceled' in o.lower():
                    chosen = o
                    break
            if chosen:
                try:
                    await cb.select_option(label=chosen)
                except Exception:
                    # fallback: try selecting by option value
                    try:
                        opt_loc = cb.get_by_role('option')
                        oc = await safe_count(opt_loc)
                        val = None
                        for oi in range(oc):
                            oel = opt_loc.nth(oi)
                            try:
                                txt = await oel.inner_text()
                            except Exception:
                                txt = ''
                            if txt and 'canceled' in txt.lower():
                                val = await oel.get_attribute('value')
                                break
                        if val:
                            await cb.select_option(value=val)
                    except Exception:
                        pass
                break
    except Exception:
        # If we can't set it, continue; maybe it's already set or will be handled by export filtering
        pass

    # 4) Click the Search button in the toolbar to apply filters. Scope via the toolbar table cell "Export to: CSV Export"
    try:
        toolbar_table = page.get_by_role('table').filter(
            has=page.get_by_role('cell', name=lambda n: bool(n) and 'Export to:' in n)
        ).first
        search_btn = toolbar_table.get_by_role('button', name='Search')
        if await safe_count(search_btn) > 0:
            await search_btn.first.click()
        else:
            # fallback: any page-level Search button
            global_search = page.get_by_role('button', name=lambda n: bool(n) and 'search' in n.lower())
            if await safe_count(global_search) > 0:
                await global_search.first.click()
    except Exception:
        pass

    await asyncio.sleep(1)

    # 5) Use the Export control in the toolbar to export current (filtered) grid to CSV
    out_path = Path('/tmp/magento_canceled_orders_export.csv')
    try:
        toolbar_table = page.get_by_role('table').filter(
            has=page.get_by_role('cell', name=lambda n: bool(n) and 'Export to:' in n)
        ).first
        export_combo = toolbar_table.get_by_role('combobox')
        if await safe_count(export_combo) > 0:
            combo = export_combo.first
            # Ensure CSV is selected (label "CSV")
            try:
                await combo.select_option(label='CSV')
            except Exception:
                try:
                    opts = await combo.get_by_role('option').all_inner_texts()
                except Exception:
                    opts = []
                for o in opts:
                    if o and 'csv' in o.lower():
                        try:
                            await combo.select_option(label=o)
                        except Exception:
                            # try value fallback
                            try:
                                option_loc = combo.get_by_role('option')
                                oc = await safe_count(option_loc)
                                for oi in range(oc):
                                    oel = option_loc.nth(oi)
                                    try:
                                        text = await oel.inner_text()
                                    except Exception:
                                        text = ''
                                    if text and 'csv' in text.lower():
                                        val = await oel.get_attribute('value')
                                        if val:
                                            await combo.select_option(value=val)
                                            break
                            except Exception:
                                pass
                        break
        export_btn = toolbar_table.get_by_role('button', name='Export')
        if await safe_count(export_btn) > 0:
            async with page.expect_download(timeout=30000) as dl_info:
                await export_btn.first.click()
            download = await dl_info.value
            await download.save_as(str(out_path))
        else:
            print('ERROR: Export button not found')
            return
    except Exception as e:
        print(f'ERROR: Export failed: {e}')
        return

    # 6) Read exported CSV and compute customer with most cancellations
    try:
        raw_bytes = out_path.read_bytes()
        try:
            raw_text = raw_bytes.decode('utf-8')
        except Exception:
            raw_text = raw_bytes.decode('latin-1', errors='replace')
    except Exception as e:
        print(f'ERROR: Could not read exported CSV: {e}')
        return

    try:
        lines = raw_text.splitlines()
        reader = _csv.reader(lines)
        rows = list(reader)
    except Exception as e:
        print(f'ERROR: Could not parse exported CSV: {e}')
        return

    if not rows:
        print('ERROR: Exported CSV is empty')
        return

    header = [h.strip() for h in rows[0]]

    def find_col(names):
        for name in names:
            for i, h in enumerate(header):
                if name.lower() in h.lower():
                    return i
        return None

    cust_idx = find_col(['Bill to Name', 'Bill to', 'Customer', 'Customer Name'])
    date_idx = find_col(['Purchased On', 'Purchased', 'Created At', 'Order Date'])

    if cust_idx is None:
        print('ERROR: Could not find customer column in CSV')
        return

    counts = Counter()
    cust_rows = {}
    for r in rows[1:]:
        if not any(cell.strip() for cell in r):
            continue
        cust = r[cust_idx].strip() if cust_idx < len(r) else ''
        if not cust:
            continue
        counts[cust] += 1
        cust_rows.setdefault(cust, []).append(r)

    if not counts:
        print('ERROR: No customer rows found in CSV')
        return

    top_customer = counts.most_common(1)[0][0]

    # 7) Determine the most recent cancelled order for that customer (from exported rows)
    candidate_rows = cust_rows.get(top_customer, [])
    most_recent_row = None
    if date_idx is not None:
        parsed = []
        from datetime import datetime
        for r in candidate_rows:
            dt_txt = r[date_idx].strip() if date_idx < len(r) else ''
            dt = None
            if dt_txt:
                for fmt in ('%b %d, %Y %I:%M:%S %p', '%b %d, %Y %I:%M %p', '%Y-%m-%d %H:%M:%S', '%m/%d/%Y %H:%M:%S'):
                    try:
                        dt = datetime.strptime(dt_txt, fmt)
                        break
                    except Exception:
                        continue
            parsed.append((dt, r))
        with_dt = [p for p in parsed if p[0] is not None]
        if with_dt:
            with_dt.sort(key=lambda x: x[0], reverse=True)
            most_recent_row = with_dt[0][1]
        else:
            most_recent_row = candidate_rows[-1] if candidate_rows else None
    else:
        most_recent_row = candidate_rows[-1] if candidate_rows else None

    if most_recent_row is None:
        print('ERROR: Could not determine most recent cancelled order for top customer')
        return

    # 8) Filter the grid by Bill to Name = top_customer to locate the order's View link
    try:
        # re-locate orders_table in case of DOM changes
        orders_table = page.get_by_role('table').filter(
            has=page.get_by_role('cell', name=lambda n: bool(n) and 'Order #' in n)
        ).first
        filter_row = orders_table.get_by_role('row').nth(1)
        cells = filter_row.get_by_role('cell')
        if await safe_count(cells) > bill_col_idx:
            target_cell = cells.nth(bill_col_idx)
            textboxes = target_cell.get_by_role('textbox')
            if await safe_count(textboxes) > 0:
                await textboxes.first.fill(top_customer)
            else:
                try:
                    await target_cell.click()
                    await page.keyboard.type(top_customer)
                except Exception:
                    pass
        # click Search in toolbar
        toolbar_table = page.get_by_role('table').filter(
            has=page.get_by_role('cell', name=lambda n: bool(n) and 'Export to:' in n)
        ).first
        search_btn = toolbar_table.get_by_role('button', name='Search')
        if await safe_count(search_btn) > 0:
            await search_btn.first.click()
    except Exception:
        pass

    await asyncio.sleep(1)

    # 9) Find the first data row matching top_customer and get its View link href
    view_href = None
    try:
        orders_table = page.get_by_role('table').filter(
            has=page.get_by_role('cell', name=lambda n: bool(n) and 'Order #' in n)
        ).first
        rows = orders_table.get_by_role('row')
        rcount = await safe_count(rows)
        for ri in range(2, rcount):
            r = rows.nth(ri)
            try:
                cells = r.get_by_role('cell')
                if await safe_count(cells) > bill_col_idx:
                    text = (await cells.nth(bill_col_idx).inner_text()) or ''
                    if top_customer.strip() in text:
                        view_link = r.get_by_role('link', name='View')
                        if await safe_count(view_link) > 0:
                            view_href = await view_link.first.get_attribute('href')
                            break
            except Exception:
                continue
    except Exception:
        pass

    if not view_href:
