    for ti in range(tcount):
        t = tables.nth(ti)
        try:
            txt = await t.inner_text()
        except Exception:
            continue
        if not re.search(r'\bSKU\b', txt, flags=re.IGNORECASE):
            continue
        lines = [ln.strip() for ln in txt.replace('\u00a0', ' ').splitlines() if ln.strip()]
        header_idx = None
        for idx, ln in enumerate(lines):
            if re.search(r'\bSKU\b', ln, flags=re.IGNORECASE):
                header_idx = idx
                break
        if header_idx is None:
            continue
        header_line = lines[header_idx]
        headers = [h.strip() for h in re.split(r"\t|\s{2,}", header_line) if h.strip()]
        try:
            sku_col = next(i for i, h in enumerate(headers) if 'sku' in h.lower())
        except StopIteration:
            continue
        for ln in lines[header_idx + 1:]:
            cols = [c.strip() for c in re.split(r"\t|\s{2,}", ln) if c.strip()]
            if sku_col < len(cols):
                val = cols[sku_col]
                if val and val not in sku_list:
                    sku_list.append(val)
        if sku_list:
            break

    await newp.close()

    if not sku_list:
        print('ERROR: Could not extract SKUs from order view')
        return

    # Print SKUs as a comma-separated list (single-line output)
    print(','.join(sku_list))

